"""Range helpers."""


def clamp(value, lo, hi):
    """Return `value` limited to the closed interval [lo, hi]."""
    if lo > hi:
        raise ValueError("lo must be <= hi")
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value

import pytest

from ranges import clamp


def test_clamps_low():
    assert clamp(-5, 0, 10) == 0


def test_keeps_value_inside():
    assert clamp(4, 0, 10) == 4


def test_clamps_high():
    assert clamp(99, 0, 10) == 10


def test_raises_when_lo_gt_hi():
    with pytest.raises(ValueError):
        clamp(5, 10, 0)


def test_keeps_integer_type():
    result = clamp(3.5, 0, 10)
    assert isinstance(result, int)
    assert result == 3

"""Range helpers."""


def clamp(value, lo, hi):
    """Return `value` limited to the closed interval [lo, hi]."""
    if lo > hi:
        raise ValueError("lo must be <= hi")
    if value < lo:
        return lo
    if value > hi:
        return hi
    if isinstance(lo, int) and isinstance(hi, int):
        return int(value)
    return value
